/**
 * docx.min.js — WordMine OpenXML DOCX Generator
 * Produces 100% valid ECMA-376 OpenXML Word (.docx) files using JSZip.
 * Compatible with Microsoft Word, Apple Pages, Google Docs, and LibreOffice.
 */
(function (root, factory) {
  if (typeof define === 'function' && define.amd) {
    define(['jszip'], factory);
  } else if (typeof module === 'object' && module.exports) {
    module.exports = factory(require('./jszip.min.js'));
  } else {
    root.docx = factory(root.JSZip);
  }
}(typeof self !== 'undefined' ? self : this, function (JSZip) {
  'use strict';

  function escapeXml(unsafe) {
    return String(unsafe || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  class TextRun {
    constructor(options) {
      options = options || {};
      this.text = options.text || '';
      this.bold = !!options.bold;
      this.size = options.size || 24; // half-points (24 = 12pt)
      this.color = options.color || '1C1C1A';
      this.font = options.font || 'Calibri';
    }

    toXml() {
      var rPr = '<w:rPr>';
      if (this.bold) rPr += '<w:b/><w:bCs/>';
      if (this.size) rPr += '<w:sz w:val="' + this.size + '"/><w:szCs w:val="' + this.size + '"/>';
      if (this.color) rPr += '<w:color w:val="' + this.color + '"/>';
      rPr += '<w:rFonts w:ascii="' + this.font + '" w:hAnsi="' + this.font + '" w:cs="' + this.font + '"/>';
      rPr += '</w:rPr>';
      return '<w:r>' + rPr + '<w:t xml:space="preserve">' + escapeXml(this.text) + '</w:t></w:r>';
    }
  }

  class Paragraph {
    constructor(options) {
      options = options || {};
      this.children = options.children || [];
      this.spacing = options.spacing || {};
    }

    toXml() {
      var pPr = '<w:pPr>';
      if (this.spacing && this.spacing.after) {
        pPr += '<w:spacing w:after="' + this.spacing.after + '"/>';
      }
      pPr += '</w:pPr>';
      var runsXml = '';
      for (var i = 0; i < this.children.length; i++) {
        var child = this.children[i];
        if (child && typeof child.toXml === 'function') {
          runsXml += child.toXml();
        }
      }
      return '<w:p>' + pPr + runsXml + '</w:p>';
    }
  }

  class Document {
    constructor(options) {
      options = options || {};
      this.sections = options.sections || [];
    }
  }

  class Packer {
    static async toZip(doc) {
      var ZipLib = (typeof JSZip !== 'undefined' && JSZip) || (typeof window !== 'undefined' && window.JSZip);
      if (!ZipLib) {
        throw new Error('JSZip is required to pack DOCX files.');
      }
      var zip = new ZipLib();

      // [Content_Types].xml
      zip.file('[Content_Types].xml',
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">' +
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>' +
        '<Default Extension="xml" ContentType="application/xml"/>' +
        '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>' +
        '</Types>'
      );

      // _rels/.rels
      zip.folder('_rels').file('.rels',
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>' +
        '</Relationships>'
      );

      // word/document.xml
      var wordFolder = zip.folder('word');
      wordFolder.folder('_rels').file('document.xml.rels',
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"/>'
      );

      var bodyXml = '';
      var sections = doc.sections || [];
      for (var s = 0; s < sections.length; s++) {
        var children = sections[s].children || [];
        for (var c = 0; c < children.length; c++) {
          if (children[c] && typeof children[c].toXml === 'function') {
            bodyXml += children[c].toXml();
          }
        }
      }
      bodyXml += '<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>';

      wordFolder.file('document.xml',
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
        '<w:body>' + bodyXml + '</w:body>' +
        '</w:document>'
      );

      return zip;
    }

    static async toBlob(doc) {
      var zip = await Packer.toZip(doc);
      return await zip.generateAsync({
        type: 'blob',
        mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      });
    }

    static async toBuffer(doc) {
      var zip = await Packer.toZip(doc);
      return await zip.generateAsync({ type: 'nodebuffer' });
    }
  }

  return {
    Document: Document,
    Paragraph: Paragraph,
    TextRun: TextRun,
    Packer: Packer
  };
}));
